import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export async function runMotionDropSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 const dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-drop-')),a=path.join(dir,'Arrastrada.svg'),b=path.join(dir,'Vertical.svg'),bad=path.join(dir,'Invalida.txt'),cdp=await page.createCDPSession();
 await fs.writeFile(a,'<svg xmlns="http://www.w3.org/2000/svg" width="300" height="180"><rect width="300" height="180" fill="tomato"/></svg>');await fs.writeFile(b,'<svg xmlns="http://www.w3.org/2000/svg" width="160" height="320"><rect width="160" height="320" fill="royalblue"/></svg>');await fs.writeFile(bad,'No es una imagen');await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});
 async function ready(){await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-motion-canvas]'));}
 async function layers(){return page.$$eval('[data-motion-layer]',ns=>ns.map(n=>({id:n.dataset.motionLayer,name:n.querySelector('strong').textContent})));}
 async function drag(type,files,point){await cdp.send('Input.dispatchDragEvent',{type,x:point.x,y:point.y,data:{items:[],files,dragOperationsMask:1}});}
 async function point(parent=false){const r=await (await page.$(parent?'.nw-motion-stage-label':'.nw-motion-dialog iframe')).boundingBox();return {x:r.x+r.width/2,y:r.y+r.height/2};}
 async function hover(files,parent=false){const p=await point(parent);await drag('dragEnter',files,p);await drag('dragOver',files,p);return p;}
 async function drop(files,parent=false){const p=await hover(files,parent);await drag('drop',files,p);}
 async function added(old,width){await page.waitForFunction(width=>{const lab=document.querySelector('.nw-motion-dialog'),n=lab.querySelector('iframe')?.contentDocument?.querySelector('.nw-motion-selected img');return !lab.querySelector('[data-motion-add-image]').disabled&&n?.complete&&n.naturalWidth===width;},{timeout:10000},width);const rows=await layers();assert.equal(rows.length,old.length+1);const row=rows.find(n=>!old.some(e=>e.id===n.id));assert.ok(row);return row;}
 try{
  await page.evaluate(()=>{const outside=mkEl('label',{name:'Exterior',text:'Fuera del grupo'});project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[outside]})];curPage=0;curSec=0;curEl=0;selection=[outside.id];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),assets:project.assets.images.length,outside:sec().elements[0]}));
  await page.click('.tb-left [data-motion-open]');await ready();await page.click('[data-motion-library-tab="elements"]');const original=await layers();
  const originals=await page.$eval('.nw-motion-dialog iframe',f=>Array.from(f.contentDocument.querySelectorAll('[data-motion-canvas] img'),n=>n.getAttribute('src')));await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.body.dataset.dropProbe='same-document');await page.click('[data-motion-play]');const start=await page.$eval('[data-motion-progress]',n=>n.value);
  await hover([a]);await page.waitForFunction(()=>!document.querySelector('[data-motion-drop-hint]').hidden);assert.equal(await page.$eval('[data-motion-drop-hint]',n=>n.textContent),'Soltá una imagen para agregarla');assert.equal(await page.$eval('.nw-motion-dialog iframe',f=>f.contentDocument.body.dataset.dropProbe),'same-document');assert.equal(await page.$eval('[data-motion-play]',n=>n.getAttribute('aria-pressed')),'true');await page.waitForFunction(start=>document.querySelector('[data-motion-progress]').value!==start,{timeout:3000},start);
  await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/image-drop-hint.png'});await drag('dragOver',[a],{x:4,y:4});await drag('dragCancel',[a],{x:4,y:4});assert.equal(await page.$eval('[data-motion-drop-hint]',n=>n.hidden),true);assert.deepEqual(await layers(),original);await page.click('[data-motion-play]');
  await drop([a]);const first=await added(original,300);assert.equal(first.name,'Imagen nueva');assert.equal(await page.$eval('[data-motion-drop-hint]',n=>n.hidden),true);assert.deepEqual(await page.$$eval('[data-motion-key] option',ns=>ns.map(n=>parseFloat(n.textContent))),[0,100]);
  assert.deepEqual(await page.$eval('.nw-motion-dialog iframe',f=>Array.from(f.contentDocument.querySelectorAll('[data-motion-canvas] img'),n=>n.getAttribute('src')).slice(0,3)),originals,'Drop adds a member rather than replacing an existing image');
  await drop([a,b]);await page.waitForFunction(()=>document.querySelector('[data-motion-add-image-status]').textContent==='Agregá una imagen por vez.');assert.equal((await layers()).length,7);
  await drop([bad],true);await page.waitForFunction(()=>document.querySelector('[data-motion-add-image-status]').textContent.includes('No se pudo'));assert.equal((await layers()).length,7,'Invalid parent-stage drop adds no member');
  await page.click('[data-motion-expand]');const old=await layers();
  await page.evaluate(()=>{window.dropNativeReader=FileReader;window.dropReads=[];window.FileReader=class extends FileReader{readAsDataURL(file){window.dropReads.push(()=>super.readAsDataURL(file));}};});
  await drop([b]);assert.equal(await page.$eval('[data-motion-insert-group]',n=>n.disabled),true);assert.equal(await page.evaluate(()=>NAGWEB_MOTION_LAB.insertGroup()),false);await hover([a]);assert.equal(await page.$eval('[data-motion-drop-hint]',n=>n.textContent),'Esperá a que termine la carga de imagen.');await drag('drop',[a],await point());assert.equal((await layers()).length,old.length,'A pending load prevents concurrent additions');await page.evaluate(()=>{window.dropReads.splice(0).forEach(fn=>fn());window.FileReader=window.dropNativeReader;delete window.dropNativeReader;delete window.dropReads;});const second=await added(old,160);assert.equal(await page.$eval('.nw-motion-dialog',n=>n.classList.contains('nw-motion-expanded')),true);assert.equal(await page.$eval('[data-motion-drop-hint]',n=>n.hidden),true);
  await page.click('[data-motion-expand]');await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/image-drop-added.png'});
  assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {gid:g.id,members:sec().elements.filter(e=>e.parent===g.id),assets:project.assets.images.length,outside:sec().elements[0],scroll:sec().sdEnabled};});assert.equal(inserted.members.length,8);assert.equal(inserted.assets,before.assets+5);assert.deepEqual(inserted.outside,before.outside);assert.equal(inserted.scroll,false);for(const [id,ratio] of [[first.id,.6],[second.id,2]]){const image=inserted.members.find(e=>e.id===id);assert.equal(image.ratio,ratio);assert.equal(image.x,50);assert.equal(image.y,50);assert.equal(image.w,36);assert.equal(image.mobile.w,48);assert.deepEqual(image.sdKeyframes.map(k=>k.at),[0,100]);}
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await ready();await page.click('[data-motion-library-tab="elements"]');const editing=await layers();await drop([a],true);const third=await added(editing,300);await page.click('[data-motion-save]');const saved=await page.evaluate(gid=>({project:JSON.stringify(project),members:sec().elements.filter(e=>e.parent===gid),groups:sec().elements.filter(e=>e.nwMotionInstance).length,outside:sec().elements[0]}),inserted.gid);assert.equal(saved.groups,1);assert.equal(saved.members.length,9);assert.deepEqual(saved.members.find(e=>e.id===first.id),inserted.members.find(e=>e.id===first.id));assert.deepEqual(saved.outside,before.outside);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='drop-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(({gid,first,second,third})=>{const f=document.querySelector('#drop-export'),d=f?.contentDocument;return f?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&d.querySelector('[data-id="'+first+'"] img')?.naturalWidth===300&&d.querySelector('[data-id="'+second+'"] img')?.naturalHeight===320&&d.querySelector('[data-id="'+third+'"] img')?.naturalWidth===300;},{},{gid:inserted.gid,first:first.id,second:second.id,third:third.id});assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  console.log('Arrastrar imágenes Motion Lab: archivos reales por CDP, aviso sin interrumpir preview, cancelar, añadir sin reemplazar, una por vez/inválida, carga pendiente bloqueada, lienzo ampliado, proporción y momentos, sin escrituras antes de insertar, Tiempo sin Director, misma instancia/externos/exportación OK');
 }catch(error){await page.screenshot({path:'/tmp/nagweb-motion-visuals/image-drop-failure.png'}).catch(()=>{});throw error;
 }finally{
  await drag('dragCancel',[],{x:4,y:4}).catch(()=>{});await cdp.detach();await page.evaluate(p=>{if(window.dropNativeReader){window.FileReader=window.dropNativeReader;delete window.dropNativeReader;delete window.dropReads;}document.querySelector('.nw-motion-dialog').close();document.querySelector('#drop-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});
 }
}
